(function(root){
'use strict';
const GOODS={grain:{name:'Trigo',product:'Pan',icon:'🌾',made:'🥖',base:8,cost:2,sale:20},copper:{name:'Cobre',product:'Cables',icon:'🧲',made:'🔌',base:15,cost:3,sale:31},oil:{name:'Petróleo',product:'Combustible',icon:'🛢️',made:'⛽',base:10,cost:2,sale:25}};
const EVENTS=[{title:'El mundo abre sus puertas',text:'Tus primeros pedidos están listos. Produce y envía antes del plazo.',delta:[0,0,0]}, {title:'Sequía en el norte',text:'La cosecha se reduce: el trigo sube.',delta:[4,0,0]}, {title:'Se enfría la construcción',text:'Baja la demanda industrial y cae el cobre.',delta:[0,-4,0]}, {title:'Tensión energética',text:'El petróleo se encarece. Tus costos cambian.',delta:[1,1,5]}, {title:'Una cosecha inesperada',text:'Llega más trigo al mercado: cae su precio.',delta:[-5,0,-1]}, {title:'Puerto congestionado',text:'Los nuevos envíos tardan un mes adicional durante dos meses.',delta:[1,2,1],delay:2}, {title:'Nueva red eléctrica',text:'La demanda de cobre acelera.',delta:[0,6,0]}, {title:'Acuerdo entre productores',text:'Se libera oferta de petróleo.',delta:[-1,0,-6]}, {title:'Tormenta sobre la cosecha',text:'El trigo vuelve a subir.',delta:[5,-2,1]}, {title:'Rutas despejadas',text:'La logística recupera su ritmo.',delta:[-2,1,-1]}, {title:'Expansión industrial',text:'Metales y energía se encarecen.',delta:[0,4,3]}, {title:'Venta de reservas',text:'Hay abundancia de materias primas.',delta:[-3,-5,-3]}, {title:'Temporada de calor',text:'Sube el consumo de energía.',delta:[2,1,4]}, {title:'Nueva cosecha',text:'El trigo baja; el cobre se mantiene.',delta:[-4,0,-2]}, {title:'Obras en el canal',text:'Dos meses con viajes más largos.',delta:[1,1,1],delay:2}, {title:'Demanda extraordinaria',text:'Suben los insumos. Los contratos de venta mantienen su precio pactado.',delta:[3,4,3]}, {title:'Vuelve la calma',text:'Se normaliza la oferta.',delta:[-2,-2,-3]}, {title:'Últimas entregas',text:'Se cierra la temporada. Completa tus rutas pendientes.',delta:[1,1,1]}];
function create(){return {month:0,end:18,cash:650,raw:{grain:10,copper:5,oil:5},made:{grain:0,copper:0,oil:0},prices:{grain:8,copper:15,oil:10},open:{grain:true,copper:false,oil:false},capacity:10,used:0,rep:3,delivered:0,shipments:[],contracts:[],hedges:[],nextId:1,delayUntil:0,rival:0,history:[],log:[],finished:false,event:EVENTS[0]};}
function note(s,t,kind='info'){s.log.unshift({month:s.month+1,text:t,kind});s.log=s.log.slice(0,40);}
function order(s,key,qty,life){const g=GOODS[key];s.contracts.push({id:s.nextId++,key,qty,reward:g.sale*qty,deadline:s.month+life,status:'open'});}
function start(){const s=create();order(s,'grain',10,4);order(s,'copper',5,5);order(s,'oil',5,6);s.history.push({...s.prices});note(s,'Tienes insumos para comenzar: fabrica tu primer pedido.');return s;}
function available(s,n){if(s.finished) return 'La temporada terminó.';if(s.cash<n)return 'No hay suficiente efectivo disponible.';return null;}
function buy(s,key,qty){if(!GOODS[key]||![5,10,20].includes(qty))return 'Cantidad inválida.';if(!s.open[key])return 'Abre primero esta ruta.';const price=s.prices[key]*qty,err=available(s,price);if(err)return err;s.cash-=price;s.shipments.push({id:s.nextId++,type:'buy',key,qty,depart:s.month,arrival:s.month+1+(s.month<s.delayUntil?1:0)});note(s,`${qty} de ${GOODS[key].name} en camino · compra $${price}.`);return null;}
function unlock(s,key){if(!GOODS[key]||s.open[key])return 'La ruta ya está abierta.';const e=available(s,75);if(e)return e;s.cash-=75;s.open[key]=true;note(s,`Nueva ruta: ${GOODS[key].name}.`,'good');return null;}
function produce(s,key,qty){if(!GOODS[key]||![5,10,20].includes(qty))return 'Cantidad inválida.';if(s.raw[key]<qty)return 'Faltan insumos en el almacén.';if(s.used+qty>s.capacity)return 'Capacidad agotada este mes. Avanza el tiempo o amplía la fábrica.';const e=available(s,GOODS[key].cost*qty);if(e)return e;s.cash-=GOODS[key].cost*qty;s.raw[key]-=qty;s.made[key]+=qty;s.used+=qty;note(s,`${qty} de ${GOODS[key].product} listos para enviar.`,'good');return null;}
function deliver(s,id){const c=s.contracts.find(c=>c.id===id);if(!c||c.status!=='open')return 'Pedido no disponible.';if(s.finished)return 'La temporada terminó.';if(s.made[c.key]<c.qty)return 'Produce primero los bienes de este pedido.';const arrival=s.month+1+(s.month<s.delayUntil?1:0);if(arrival>c.deadline)return 'El envío llegaría fuera de plazo. Prioriza otro pedido.';s.made[c.key]-=c.qty;c.status='shipping';s.shipments.push({id:s.nextId++,type:'sale',key:c.key,qty:c.qty,contract:id,depart:s.month,arrival});note(s,`Pedido de ${GOODS[c.key].product} enviado. Cobrarás $${c.reward} al llegar.`);return null;}
function upgrade(s){if(s.capacity===20)return 'Tu fábrica ya tiene la ampliación.';const e=available(s,160);if(e)return e;s.cash-=160;s.capacity=20;note(s,'Fábrica ampliada: 20 unidades por mes.','good');return null;}
function hedge(s,key,type,qty=10){if(!GOODS[key]||!['future','call'].includes(type)||qty!==10)return 'Contrato inválido.';if(s.month+3>s.end-1)return 'Ya no hay tres meses para abrir este contrato.';if(s.hedges.filter(h=>!h.closed).length>=3)return 'Máximo tres coberturas abiertas.';const deposit=type==='future'?qty*3:qty*2,e=available(s,deposit);if(e)return e;s.cash-=deposit;const h={id:s.nextId++,key,type,qty,strike:s.prices[key],last:s.prices[key],expiry:s.month+3,margin:type==='future'?deposit:0,premium:type==='call'?deposit:0,pnl:0,closed:false};s.hedges.push(h);note(s,type==='future'?`Futuro largo: ${qty} ${GOODS[key].name} a $${h.strike}. $30 quedan en garantía.`:`Call: derecho por ${qty} ${GOODS[key].name} a $${h.strike}. Pagas $20 por flexibilidad.`);return null;}
function close(s,id){const h=s.hedges.find(h=>h.id===id&&!h.closed);if(!h)return 'Contrato no disponible.';if(h.type==='call')return 'La call se liquida al vencimiento.';s.cash+=h.margin;h.margin=0;h.closed=true;note(s,`Futuro cerrado. Resultado acumulado: ${signed(h.pnl)}. Garantía devuelta.`);return null;}
function signed(n){return `${n>=0?'+':'−'}$${Math.abs(n)}`;}
function tick(s){if(s.finished)return;s.month++;s.used=0;if(s.month<s.end){s.event=EVENTS[s.month];if(s.event.delay)s.delayUntil=s.month+s.event.delay;Object.keys(GOODS).forEach((k,i)=>s.prices[k]=Math.max(3,s.prices[k]+s.event.delta[i]));s.history.push({...s.prices});note(s,s.event.title);}
for(const h of s.hedges.filter(h=>!h.closed)){if(h.type==='future'){const change=(s.prices[h.key]-h.last)*h.qty;h.last=s.prices[h.key];h.pnl+=change;s.cash+=change;if(change)note(s,`Futuro de ${GOODS[h.key].name}: ajuste ${signed(change)} en efectivo.`,change>0?'good':'bad');if(s.cash<0){s.cash+=h.margin;h.margin=0;h.closed=true;note(s,'Falta liquidez: se cierra un futuro y se libera su garantía.','bad');}}
if(!h.closed&&s.month>=h.expiry){if(h.type==='call'){const payout=Math.max(0,s.prices[h.key]-h.strike)*h.qty;h.pnl=payout-h.premium;s.cash+=payout;note(s,`Call vencida: cobras $${payout}; resultado neto ${signed(h.pnl)}.`,h.pnl>=0?'good':'bad');}else{s.cash+=h.margin;h.margin=0;note(s,`Futuro vencido: ${signed(h.pnl)} acumulados; garantía devuelta.`,h.pnl>=0?'good':'bad');}h.closed=true;}}
for(const ship of s.shipments.filter(x=>x.arrival<=s.month)){if(ship.type==='buy'){s.raw[ship.key]+=ship.qty;note(s,`Llegaron ${ship.qty} de ${GOODS[ship.key].name}.`,'good');}else{const c=s.contracts.find(c=>c.id===ship.contract);c.status='done';s.cash+=c.reward;s.delivered++;s.rep=Math.min(5,s.rep+1);note(s,`¡Entrega! +$${c.reward} · ${GOODS[c.key].product}.`,'good');}}s.shipments=s.shipments.filter(x=>x.arrival>s.month);
for(const c of s.contracts.filter(c=>c.status==='open'&&s.month>=c.deadline)){c.status='missed';s.rep=Math.max(0,s.rep-1);s.cash-=20;note(s,`Pedido de ${GOODS[c.key].product} perdido: penalización $20.`,'bad');}
if(s.month<s.end-3&&s.month%2===0){const k=Object.keys(GOODS)[(s.month/2-1)%3];order(s,k,10,5);}
s.rival=Math.min(8,Math.floor(s.month/2));if(s.cash<0||s.rep===0||s.month>=s.end-1){s.finished=true;for(const h of s.hedges.filter(h=>!h.closed)){if(h.type==='future'){s.cash+=h.margin;h.margin=0;h.closed=true;}}note(s,'La temporada ha terminado.');}}
function value(s){return Math.round(s.cash+Object.keys(GOODS).reduce((a,k)=>a+s.raw[k]*s.prices[k]+s.made[k]*GOODS[k].sale,0)+s.shipments.reduce((a,t)=>a+(t.type==='buy'?t.qty*s.prices[t.key]:s.contracts.find(c=>c.id===t.contract).reward),0)+s.hedges.filter(h=>!h.closed).reduce((a,h)=>a+h.margin+(h.type==='call'?Math.max(0,s.prices[h.key]-h.strike)*h.qty:0),0));}
function result(s){return {value:value(s),won:s.delivered>=7&&value(s)>=1200&&s.rep>0&&s.cash>=0};}
const api={GOODS,EVENTS,start,buy,unlock,produce,deliver,upgrade,hedge,close,tick,value,result};if(typeof module==='object'&&module.exports)module.exports=api;else root.TradeGame=api;
})(typeof globalThis==='object'?globalThis:this);
